INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES
(5141, 'ruRU', 'Да будет этот неудавшийся король навеки погребён в собственном трупе до конца времён.$b$BПусть имя его будет стёрто из памяти, а наследие сгниёт на корню.$b$bТакова судьба тех, кто посмел бросить вызов мистикам.'),
(5158, 'ruRU', 'Лифтбрул, величайший силач ("Нет, эту часть вычеркни!") среди всех дрогбаров, чемпион Тёмнокаменных.\n\nУвековечен в камне вождём Рыноксом, вторым по силе дрогбаром своего времени ("Что ты там пишешь, Резчик камня?").\n\nЭто не статуя, это Лифтбрул. Рынокс — Ваятель камня ("Там написано что-нибудь хорошее про меня?").'),
(5210, 'ruRU', 'В честь тех, кто поднялся на немыслимые высоты. Пусть ваш дух продолжит жить в мечтах тех, кто последует за вами...'),
(5260, 'ruRU', '- НЕ ВХОДИТЬ -\n\nВ этом районе были замечены агенты Легиона.\n\nПожалуйста, немедленно сообщайте о любой подозрительной активности стражу Альтурасу в Аметистовой цитадели.'),
(5308, 'ruRU', 'НЕПОКОРНОСТЬ ФАРОНДИСА\n\nДоговор королевы Азшары с повелителем демонов Саргерасом почти не встретил сопротивления среди её подданных. Одним из немногих, кто осмелился бросить ей вызов, был принц Фарондис.\n\nБудучи одним из доверенных советников королевы, Фарондис регулярно общался с Высокородными Зин-Ашари, но его дворец в Азсуне находился в нескольких лигах от эльфийской столицы. Благодаря этому он смог наблюдать за влиянием Саргераса на двор Высокородных, не поддавшись соблазнам демонов.'),
(5309, 'ruRU', 'ГНЕВ КОРОЛЕВЫ\n\nПлан Фарондиса был смелым, но простым: уничтожить Колодец Вечности в Зин-Ашари. Это закрыло бы портал во владения Саргераса и остановило бы волну зла ещё до её начала. Чтобы выполнить эту задачу, он собирался использовать силу артефакта, хранившегося глубоко в академии Нар''талас: Камня приливов Голганнета.\n\nК несчастью, влияние королевы во дворце Фарондиса уже укоренилось глубоко. Вандрос, молодой дворянин из свиты Фарондиса, узнал о его планах бросить вызов королеве и донёс о заговоре самой королеве Азшаре.'),
(5310, 'ruRU', 'СУДЬБА АЗСУНЫ\n\nАзшара не теряла времени и покарала Фарондиса и его народ. В пугающей демонстрации чародейской силы она уничтожила Камень приливов Голганнета, тем самым выпустив волну тёмной энергии над всей Азсуной и её жителями.\n\nС того дня эльфы Азсуны не способны обрести освобождение смерти. Их духи — наши духи — бесконечно скитаются по этим землям... и всё из-за неразумной верности нашего принца.'),
(5332, 'ruRU', 'Здесь покоятся Верные Зову. $b$bОтважная Аэлинн и благородный Банлорус властвовали как на полях битв, так и при дворе. Они погибли так же, как жили — защищая наш народ от угроз со всех сторон.$b$bАну Дора. Мы помним.'),
(5333, 'ruRU', 'Здесь покоится Дорендил Дикий Зов.$b$bЕго звала к себе как природа, так и общество, и он был одним из первых, кто заговорил с гиппогрифами. Его наследие живёт в нашем вечном родстве с ними.$b$bАну Дора. Мы помним.'),
(5334, 'ruRU', 'Здесь покоится Лилиана Лугоклинок.$b$bЕё клинок не знал равных и скользил среди врагов, словно травинка танцует на ветру.$b$bАну Дора. Мы помним.'),
(5335, 'ruRU', 'Здесь покоятся Ветроборцы.$b$bСтрелки без равных, их мастерство владения луком стало вдохновением для поколений лучников.$b$bИх семья создала перчатки, которые носят часовые — искусно сочленённые кольчужные звенья, что по сей день усиливают наших лучников.$b$bАну Дора. Мы помним.'),
(5336, 'ruRU', 'Колокольчики Луны$b$bСёстры говорят, что Элуна поёт песню, чистую и прекрасную в каждой ноте.$b$bКолокольчик звонит нечасто, но когда это происходит, звучит та же нота, что поёт Она.$b$bЗин-ал Элуна.'),
(5337, 'ruRU', 'Здесь покоится Латара Перосвет.$b$bОхотница часовых, она вела авангард во многих походах. Её отвага и сострадание были безграничны.$b$bАну Дора. Я помню.'),
(5788, 'ruRU', '<HTML><BODY>\n<H1 align="center">Том древних</H1>\n<IMG src="Interface\\Common\\spacer" align="center" width="1" height="27"/>\n<IMG src="Interface\\Pictures\\artifactbook-druid-cover" align="center" width="230" height="230"/>\n<IMG src="Interface\\Common\\spacer" align="center" width="1" height="27"/>\n<p align="center">Записано Селадайн, главным историком Ткачей Снов.</p>\n</BODY></HTML>'),
(6283, 'ruRU', 'Этот вольер тщательно спроектирован нашими сотрудниками, чтобы воспроизвести пустынные пустоши.$b$bЗНАЕТЕ ЛИ ВЫ? Наши учёные полагают, что если бы мы не возвели щит, Сурамар мог бы выглядеть именно так!$b$bЗНАЕТЕ ЛИ ВЫ? Раньше василиски водились по всему Сурамару! Из-за активной охоты на них ради глаз они оказались на грани исчезновения, и лишь немногие виды до сих пор выживают в отдалённых местах.$b$bВасилиски используют свой могучий взгляд, чтобы обращать жертв в камень, потому что едят камни!$b$bНаших василисков, конечно же, регулярно кормят камнями и цветами, чтобы поддерживать блеск их чешуи. Не смотрите на них слишком долго!$b$b$b$bПРИМЕЧАНИЕ: ПОЖАЛУЙСТА, не смотрите на василисков слишком долго. Администрация не несёт ответственности за дополнительные расходы на снятие окаменения.'),
(6284, 'ruRU', 'Этот ров точно воспроизводит ландшафт джунглевых низин. Говорят, что именно здесь зародилась жизнь! В этом вольере вы найдёте Старину Мудрого, нашего постоянного йети.$b$bЗНАЕТЕ ЛИ ВЫ?$b$bСтарине Мудрому не потребовался ошейник подчинения, чтобы пойти с нами. Наши лучшие ловцы поняли, что у него есть тяга к козам, и приманили его обратно в город. Похоже, он доволен тем, что сидит здесь и ест коз. Говорят, сама Магистрикс похвалила его за мудрое поведение, и с тех пор его с любовью зовут "Старина Мудрый".$b$b$b$bПОЖАЛУЙСТА, НЕ ГНЕВИТЕ СТАРИНУ МУДРОГО — Администрация.'),
(6285, 'ruRU', 'Этот вольер точно воспроизводит бесплодный ландшафт, где процветают эти существа.$b$bЗНАЕТЕ ЛИ ВЫ? Тигры — пушистые и очень тёплые друзья. Они идеально подходят, чтобы прижаться к ним в холодную ночь, если бы не то, что наша погода находится под магическим контролем. Почешите их за ушком, и вы обязательно услышите прекрасное мурлыканье.$b$bЗНАЕТЕ ЛИ ВЫ? Однороги внутри — редкая порода, их характерные шкуры используются для всевозможной моды, включая шляпы, подкладки для пальто и прочие изысканные изделия.$b$bВ зоологическом сообществе идут споры о том, не назвать ли этих величественных существ "единорогами", но большинство сходится на том, что "однорог" — более подходящее название.$b$b$b$bПОЖАЛУЙСТА, НЕ ТРОГАЙТЕ ЭКСПОНАТЫ — Администрация.'),
(6287, 'ruRU', 'ЕЖЕДНЕВНАЯ ДЕМОНСТРАЦИЯ КОРМЛЕНИЯ$b$bСпросите у любого из наших сотрудников о времени кормления и о том, как пройти в наш магазин подарков!$b$bЗНАЕТЕ ЛИ ВЫ? Морские львы-тюлени получили своё название благодаря грозному рыку, похожему на рык обычного наземного льва. Мы полагаем, что неволя сделала их застенчивыми, поэтому они больше не рычат.$b$bВот почему усилия по сохранению природы так важны. Ваше небольшое пожертвование Зверинцу поможет нам расширить экспозиции на тысячелетия вперёд!');
